mapper.select:
/* Staff.findStaffList */
select
	row_number() over(order by staff_id desc) as num, a.*
from (
	select *
	from staff
	where 1=1
	
	and staff_id like concat('%', #{searchText}, '%')
	
	
	order by 
		
			
				staff_id ${orderType}
			
			
				staff_id desc
			
		
	
	limit #{firstIndex}, #{recordCountPerPage}
) a

/* Staff.getStaffInfo */
select
	staff_id
	, staff_name
from staff
where staff_id = #{staffId}
and password = #{password}
